import random
import string
from typing import List

# Generate valid HTTP header values aiming to cover RFC 7230 and stricter RFC 9113 checks.
# We produce a variety of values: tokens, quoted-strings with escapes, comma-separated lists,
# cache-control style directives, cookie-like pairs, obs-text presence, whitespace edge cases,
# and boundary sizes. The output is bytes suitable for FUZZ_PARAM_STR.

_CTL = [chr(c) for c in range(0x00, 0x20)] + [chr(0x7f)]
_VCHAR = [chr(c) for c in range(0x21, 0x7e + 1)]
_SPHT = [' ', '\t']
_OBS_TEXT = [chr(c) for c in range(0x80, 0xff + 1)]

# Characters commonly allowed inside quoted-string (excluding \" which will be escaped).
_QTEXT = [c for c in _VCHAR if c not in ['\\', '"']] + _SPHT

# Visible ASCII excluding separators that are often problematic; keep commas/semicolons/equals to build lists
_VISIBLE_VALUE_CHARS = (
    [c for c in _VCHAR if c not in ['\r', '\n']] + _SPHT
)

# For RFC 7230 header value (obs-text allowed in older check), we sometimes include OBS_TEXT.


def _rand_bytes_from(chars: List[str], k: int, rnd: random.Random) -> bytes:
    return ''.join(rnd.choice(chars) for _ in range(k)).encode('latin-1')


def _make_token(rnd: random.Random, minlen=1, maxlen=16) -> str:
    tchar = "!#$%&'*+-.^_`|~" + string.digits + string.ascii_letters
    n = rnd.randint(minlen, maxlen)
    return ''.join(rnd.choice(tchar) for _ in range(n))


def _make_quoted_string(rnd: random.Random, minlen=0, maxlen=40) -> str:
    n = rnd.randint(minlen, maxlen)
    s = []
    for _ in range(n):
        ch = rnd.choice(_QTEXT + ['\\', '"'])
        if ch in ['\\', '"']:
            # escape it
            s.append('\\' + ch)
        else:
            s.append(ch)
    return '"' + ''.join(s) + '"'


def _maybe_ws(rnd: random.Random, maxn=3) -> str:
    if rnd.random() < 0.7:
        return ''
    return ''.join(rnd.choice(_SPHT) for _ in range(rnd.randint(1, maxn)))


def _list_of_values(rnd: random.Random) -> str:
    # Create a comma-separated list of values, optionally with parameters
    parts = []
    m = rnd.randint(1, 6)
    for _ in range(m):
        base = rnd.choice([
            _make_token(rnd, 1, 12),
            _make_quoted_string(rnd, 0, 12),
        ])
        # Optional parameters like ;q=0.7 or ;charset=utf-8
        pcount = rnd.choices([0, 1, 2], weights=[5, 3, 1])[0]
        params = []
        for _p in range(pcount):
            pname = _make_token(rnd, 1, 10)
            if rnd.random() < 0.5:
                pval = _make_token(rnd, 1, 8)
            else:
                pval = _make_quoted_string(rnd, 0, 10)
            params.append(';' + _maybe_ws(rnd) + pname + '=' + pval)
        parts.append(base + ''.join(params))
    return (',').join(_maybe_ws(rnd) + p + _maybe_ws(rnd) for p in parts)


def _cache_control_like(rnd: random.Random) -> str:
    directives = [
        'no-cache', 'no-store', 'max-age', 's-maxage', 'public', 'private',
        'must-revalidate', 'proxy-revalidate', 'immutable'
    ]
    parts = []
    for _ in range(rnd.randint(1, 6)):
        d = rnd.choice(directives)
        if d in ('max-age', 's-maxage'):
            v = str(rnd.randint(0, 86400))
            parts.append(d + '=' + v)
        elif d == 'private' and rnd.random() < 0.4:
            parts.append(d + '="' + ','.join(_make_token(rnd, 3, 8) for _ in range(rnd.randint(1, 3))) + '"')
        else:
            parts.append(d)
    return ', '.join(parts)


def _cookie_like(rnd: random.Random) -> str:
    pairs = []
    for _ in range(rnd.randint(1, 4)):
        name = _make_token(rnd, 1, 10)
        if rnd.random() < 0.5:
            val = _make_token(rnd, 0, 20)
        else:
            # Restrict to cookie-octet-ish subset
            raw = _rand_bytes_from([c for c in _VISIBLE_VALUE_CHARS if c not in [';', ',']], rnd.randint(0, 20), rnd)
            val = raw.decode('latin-1')
        pairs.append(f"{name}={val}")
    return '; '.join(pairs)


def _obs_text_mix(rnd: random.Random) -> bytes:
    # Mix visible ASCII with obs-text bytes (>=0x80). Suitable for rfc7230 check variant.
    total = rnd.randint(1, 200)
    out = bytearray()
    for _ in range(total):
        if rnd.random() < 0.2:
            out.append(rnd.randint(0x80, 0xFF))
        else:
            out.append(ord(rnd.choice(_VISIBLE_VALUE_CHARS)))
    return bytes(out)


def _build_value(rnd: random.Random) -> bytes:
    choice = rnd.random()
    if choice < 0.12:
        # Simple token-only value
        s = _make_token(rnd, 1, 40)
        return s.encode('ascii')
    elif choice < 0.24:
        # Quoted-string with escapes
        s = _make_quoted_string(rnd, 0, 60)
        return s.encode('latin-1')
    elif choice < 0.38:
        # Comma-separated list with parameters
        s = _list_of_values(rnd)
        return s.encode('latin-1')
    elif choice < 0.52:
        # Cache-Control-like header value
        s = _cache_control_like(rnd)
        return s.encode('latin-1')
    elif choice < 0.64:
        # Cookie-like pairs
        s = _cookie_like(rnd)
        return s.encode('latin-1')
    elif choice < 0.76:
        # Value with optional leading/trailing whitespace (but no CR/LF)
        core = _list_of_values(rnd)
        s = _maybe_ws(rnd, 5) + core + _maybe_ws(rnd, 5)
        return s.encode('latin-1')
    elif choice < 0.88:
        # Long visible value near limits but under 4096
        length = rnd.randint(100, 1000)
        return _rand_bytes_from([c for c in _VISIBLE_VALUE_CHARS if c not in ['\r', '\n']], length, rnd)
    else:
        # Include obs-text mix for the looser validator; still valid bytes for latin-1
        return _obs_text_mix(rnd)


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Build multiple candidate segments and randomly choose one, sometimes concatenate
    segments = []
    count = rnd.randint(1, 3)
    for _ in range(count):
        seg = _build_value(rnd)
        segments.append(seg)
    sep = rnd.choice([b', ', b'; ', b' ']) if len(segments) > 1 else b''
    out = sep.join(segments)

    # Ensure size cap
    if len(out) > 4096:
        out = out[:4096]

    # Avoid embedding CR/LF which are generally invalid inside single header field-value per these validators
    out = out.replace(b"\r", b" ").replace(b"\n", b" ")

    # Occasionally produce empty value (allowed in many headers and interesting for validators)
    if rnd.random() < 0.05:
        out = b''

    return out

import random
import string
from typing import List

# Generator for valid HTTP/2 :path pseudo-header values
# Focus: characters allowed by RFC 7540 section 8.1.2.3 and typical URI path/query usage.
# We avoid SP and HT, and build absolute-path (starting with '/') with optional query and fragment.

_unreserved = string.ascii_letters + string.digits + "-._~"
_sub_delims = "!$&'()*+,;="
_pchar_extra = ":@"  # additional allowed in pchar
# pct-encoded will be produced as %HH where H is hex digit
_hex = "0123456789ABCDEF"

# Allowed query characters: pchar / "/" / "?"
# We'll build from pchar plus '/' and '?'


def _rand_pct_encoded(rng: random.Random) -> str:
    return "%" + rng.choice(_hex) + rng.choice(_hex)


def _rand_pchar(rng: random.Random) -> str:
    choice = rng.randrange(0, 10)
    if choice <= 5:
        return rng.choice(_unreserved)
    elif choice <= 7:
        return rng.choice(_sub_delims)
    elif choice == 8:
        return rng.choice(_pchar_extra)
    else:
        return _rand_pct_encoded(rng)


def _gen_segment(rng: random.Random, min_len: int = 0, max_len: int = 20) -> str:
    n = rng.randint(min_len, max_len)
    return "".join(_rand_pchar(rng) for _ in range(n))


def _gen_path_abempty(rng: random.Random, max_segments: int = 6) -> str:
    # path-abempty  = *( "/" segment )
    segs: List[str] = []
    k = rng.randint(0, max_segments)
    for _ in range(k):
        segs.append("/" + _gen_segment(rng))
    return "".join(segs)


def _gen_path_absolute(rng: random.Random, max_segments: int = 6) -> str:
    # Ensure leading '/'
    segs: List[str] = ['/']
    k = rng.randint(0, max_segments)
    for i in range(k):
        # occasionally generate empty segment for sequences like '//'
        if rng.random() < 0.15 and i > 0:
            segs.append('/')
        else:
            segs.append(_gen_segment(rng))
        if i != k - 1:
            segs.append('/')
    return "".join(segs)


def _gen_matrix_params(rng: random.Random) -> str:
    # Optional semicolon params in a segment: ";" key[="value"] repeated
    if rng.random() < 0.3:
        return ""
    parts = []
    count = rng.randint(0, 3)
    for _ in range(count):
        key = _gen_token(rng, allowed=_unreserved)
        if rng.random() < 0.5:
            val = _gen_token(rng, allowed=_unreserved + _sub_delims)
            parts.append(";" + key + "=" + val)
        else:
            parts.append(";" + key)
    return "".join(parts)


def _gen_token(rng: random.Random, min_len: int = 1, max_len: int = 12, allowed: str = _unreserved + _sub_delims) -> str:
    n = rng.randint(min_len, max_len)
    return "".join(rng.choice(allowed) for _ in range(n))


def _gen_query(rng: random.Random) -> str:
    if rng.random() < 0.3:
        return ""
    # Build either key=value pairs or arbitrary pchar with '/' and '?'
    if rng.random() < 0.6:
        pairs = []
        count = rng.randint(1, 6)
        for i in range(count):
            key = _gen_token(rng, allowed=_unreserved + _sub_delims)
            if rng.random() < 0.8:
                val = _gen_token(rng, allowed=_unreserved + _sub_delims + ":@")
            else:
                # sometimes percent-encode
                val = _gen_segment(rng, 0, 10)
            pairs.append(key + ("=" + val if rng.random() < 0.9 else ""))
        sep = '&' if rng.random() < 0.8 else ';'
        q = sep.join(pairs)
    else:
        # arbitrary allowed characters in query
        length = rng.randint(0, 40)
        allowed = _unreserved + _sub_delims + _pchar_extra + "/?"
        qchars = []
        for _ in range(length):
            if rng.random() < 0.1:
                qchars.append(_rand_pct_encoded(rng))
            else:
                qchars.append(rng.choice(allowed))
        q = "".join(qchars)
    return "?" + q


def _gen_fragment(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return ""
    length = rng.randint(0, 20)
    allowed = _unreserved + _sub_delims + _pchar_extra + "/?"
    chars = []
    for _ in range(length):
        if rng.random() < 0.15:
            chars.append(_rand_pct_encoded(rng))
        else:
            chars.append(rng.choice(allowed))
    return "#" + "".join(chars)


def _gen_path(rng: random.Random) -> str:
    style = rng.random()
    if style < 0.5:
        path = _gen_path_absolute(rng)
    else:
        # Build with segments and optional matrix params
        seg_count = rng.randint(1, 6)
        segments = []
        for _ in range(seg_count):
            segments.append(_gen_segment(rng))
            segments.append(_gen_matrix_params(rng))
        path = "/" + "/".join(s for s in segments if s is not None)
    # Special cases to exercise parsers
    specials = [
        "/",  # root
        "/.",
        "/..",
        "/./a/../b/./c",
        "/%2E%2E/..//a",
    ]
    if rng.random() < 0.15:
        path = rng.choice(specials)
    return path


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose among diverse valid path patterns
    variant = rng.randrange(0, 8)

    if variant == 0:
        path = _gen_path(rng)
    elif variant == 1:
        path = _gen_path(rng) + _gen_query(rng)
    elif variant == 2:
        path = _gen_path(rng) + _gen_query(rng) + _gen_fragment(rng)
    elif variant == 3:
        # only query (valid per RFC when path is '*', but :path generally should start with '/').
        # We generate "/" plus query to be safe for HTTP/2 :path.
        path = "/" + _gen_query(rng)
    elif variant == 4:
        # star path is valid in HTTP/1.1 options, but for HTTP/2 :path MUST NOT be '*'. Use single '/'.
        path = "/"
    elif variant == 5:
        # deep nested path
        depth = rng.randint(5, 20)
        parts = ["/"]
        for i in range(depth):
            parts.append(_gen_segment(rng, 1, 8))
            if i != depth - 1:
                parts.append("/")
        path = "".join(parts) + _gen_query(rng)
    elif variant == 6:
        # percent-encoded heavy
        segs = []
        count = rng.randint(1, 8)
        for _ in range(count):
            n = rng.randint(1, 8)
            seg = ''.join(_rand_pct_encoded(rng) if rng.random() < 0.7 else rng.choice(_unreserved) for _ in range(n))
            segs.append(seg)
        path = "/" + "/".join(segs)
    else:
        # include sub-delims and pchar extras
        segs = []
        count = rng.randint(1, 6)
        for _ in range(count):
            segs.append(_gen_segment(rng, 1, 12))
        path = "/" + "/".join(segs)
        if rng.random() < 0.7:
            path += _gen_query(rng)

    # Ensure no SP or HT are present (we never introduce them, but double-check)
    path = path.replace("\t", "").replace(" ", "")

    # Bound length to 4096
    if len(path) > 4096:
        path = path[:4096]

    return path.encode("ascii", errors="strict")

import random
import string
from typing import List

# Generator for valid :authority / Host header values
# Covers:
# - reg-name hosts with labels and optional port
# - punycode-like labels with hyphens
# - single-label hosts
# - IPv4 literals with optional port
# - IPv6 literals in brackets with optional zone id and port
# - IPvFuture per RFC 3986 (e.g., [v1.aB3]) with optional port
# - Optional userinfo is technically not allowed in Host header, but
#   nghttp2_check_authority treats '@' as valid. Include some variants
#   with userinfo@host to exercise that path while keeping allowed chars.
# All strings avoid spaces and HT.

MAX_LEN = 255  # keep inputs small and practical

LABEL_CHARS = string.ascii_lowercase + string.digits  # lowercase per RFC for hostnames
REG_NAME_EXTRA = "-._~"  # unreserved extras allowed in reg-name
PCT_HEX = string.hexdigits.lower()


def rand_choice_weighted(rnd: random.Random, items: List[tuple]):
    # items: list of (value, weight)
    total = sum(w for _, w in items)
    r = rnd.uniform(0, total)
    upto = 0.0
    for v, w in items:
        if upto + w >= r:
            return v
        upto += w
    return items[-1][0]


def gen_label(rnd: random.Random) -> str:
    # DNS label: start/end alnum, may contain hyphen inside
    length = rnd.randint(1, 63)
    if length == 1:
        return rnd.choice(string.ascii_lowercase + string.digits)
    chars = LABEL_CHARS + "-"
    while True:
        s = ''.join(rnd.choice(chars) for _ in range(length))
        if s[0] == '-' or s[-1] == '-':
            continue
        return s


def gen_reg_name(rnd: random.Random) -> str:
    # reg-name can include unreserved, pct-encoded, sub-delims
    # We'll mostly generate DNS-like names with optional pct-encoded segments
    labels = [gen_label(rnd) for _ in range(rnd.randint(1, 4))]
    host = '.'.join(labels)
    # Occasionally add pct-encoded or sub-delims in a label (allowed in reg-name)
    if rnd.random() < 0.2:
        ins_pos = rnd.randint(0, len(host))
        if rnd.random() < 0.5:
            # pct-encoded "%HH"
            hh = rnd.choice(PCT_HEX[:16]) + rnd.choice(PCT_HEX[:16])
            host = host[:ins_pos] + '%' + hh + host[ins_pos:]
        else:
            subdelims = "!$&'()*+,;="
            host = host[:ins_pos] + rnd.choice(subdelims) + host[ins_pos:]
    return host


def gen_port(rnd: random.Random) -> str:
    if rnd.random() < 0.7:
        return str(rnd.randint(1, 65535))
    return "0"  # edge


def gen_ipv4(rnd: random.Random) -> str:
    # Allow typical and edge octets
    octets = []
    for _ in range(4):
        choice = rand_choice_weighted(rnd, [
            (0, 1), (1, 1), (255, 1), (rnd.randint(2, 254), 5)
        ])
        octets.append(str(choice))
    return '.'.join(octets)


def gen_hexdigits(rnd: random.Random, n: int) -> str:
    return ''.join(rnd.choice('0123456789abcdef') for _ in range(n))


def gen_ipv6(rnd: random.Random) -> str:
    # Build an IPv6 address with possible :: compression, IPv4-embedded tail, and optional zone id
    # Strategy: generate 8 groups, then randomly compress a run of zeros
    groups = [format(rand_choice_weighted(rnd, [
        (0, 2), (rnd.randint(1, 0xFFFF), 8)
    ]), 'x') for _ in range(8)]
    # Optionally embed IPv4 at end (last 2 groups)
    if rnd.random() < 0.2:
        ipv4 = gen_ipv4(rnd)
        # replace last two groups with IPv4
        groups = groups[:6] + [ipv4]
    # Apply :: compression
    if rnd.random() < 0.8 and len(groups) == 8:
        # choose a zero run
        zero_runs = []
        i = 0
        while i < 8:
            if int(groups[i], 16) == 0:
                j = i
                while j < 8 and int(groups[j], 16) == 0:
                    j += 1
                zero_runs.append((i, j))
                i = j
            else:
                i += 1
        if zero_runs:
            start, end = rnd.choice(zero_runs)
            left = ':'.join(groups[:start])
            right = ':'.join(groups[end:])
            if left and right:
                addr = left + '::' + right
            elif left:
                addr = left + '::'
            elif right:
                addr = '::' + right
            else:
                addr = '::'
        else:
            addr = ':'.join(groups)
    else:
        addr = ':'.join(groups)
    # Optional zone id
    if rnd.random() < 0.15:
        # RFC 6874 zone id percent-encoded inside brackets, but nghttp2_check_authority just checks allowed chars
        zone = rnd.choice(['eth0', 'en0', 'lo', gen_hexdigits(rnd, rnd.randint(1, 4))])
        addr += '%' + zone
    return addr


def gen_ipfuture(rnd: random.Random) -> str:
    vers = rnd.choice('0123456789abcdef')
    tail_len = rnd.randint(1, 8)
    tail_chars = string.ascii_letters + string.digits + "._-~:"
    tail = ''.join(rnd.choice(tail_chars) for _ in range(tail_len))
    return f"v{vers}.{tail}"


def maybe_userinfo(rnd: random.Random) -> str:
    if rnd.random() < 0.2:
        # Allowed char set without spaces; keep simple
        uchars = string.ascii_letters + string.digits + "-._~!$&'()*+,;=:"  # include ':' for password-like
        name = ''.join(rnd.choice(uchars) for _ in range(rnd.randint(1, 8)))
        if rnd.random() < 0.5:
            pwd = ''.join(rnd.choice(uchars) for _ in range(rnd.randint(0, 6)))
            if pwd:
                name = name + ':' + pwd
        return name + '@'
    return ''


def build_authority(rnd: random.Random) -> str:
    kind = rand_choice_weighted(rnd, [
        ('reg', 50), ('ipv4', 15), ('ipv6', 25), ('ipfuture', 5), ('single', 5)
    ])
    ui = maybe_userinfo(rnd)
    host = ''
    if kind == 'reg':
        host = gen_reg_name(rnd)
    elif kind == 'ipv4':
        host = gen_ipv4(rnd)
    elif kind == 'ipv6':
        host = '[' + gen_ipv6(rnd) + ']'
    elif kind == 'ipfuture':
        host = '[' + gen_ipfuture(rnd) + ']'
    elif kind == 'single':
        # single label like localhost
        host = rnd.choice(['localhost', 'local', 'intranet'])
    # Optional port
    port = ''
    if rnd.random() < 0.6:
        port = ':' + gen_port(rnd)
    authority = ui + host + port
    # Trim to MAX_LEN if necessary (avoid cutting inside brackets if possible)
    if len(authority) > MAX_LEN:
        if authority.startswith('['):
            # keep bracket structure; drop port if needed
            if ']' in authority:
                end = authority.index(']') + 1
                base = authority[:end]
                rest = authority[end:]
                truncated = base + rest[: max(0, MAX_LEN - len(base))]
                return truncated
        authority = authority[:MAX_LEN]
    return authority


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Randomly create a few different authorities and choose one to return to provide variance per seed
    variants = [build_authority(rnd) for _ in range(rnd.randint(1, 5))]
    s = rnd.choice(variants)
    return s.encode('ascii', 'strict')
